create table projects (id uuid primary key default gen_random_uuid(), user_id uuid not null, name text not null, repository text, default_branch text default 'main', created_at timestamptz default now(), updated_at timestamptz default now());
create table scans (id text primary key, project_id uuid references projects(id), commit_sha text, status text not null, score integer, score_algorithm_version text, started_at timestamptz default now(), completed_at timestamptz);
create table findings (id text primary key, scan_id text references scans(id), rule_id text not null, severity text not null, category text not null, file text not null, line_start integer not null, line_end integer not null, confidence numeric not null, title text not null, description text not null, impact text not null, status text not null default 'OPEN', created_at timestamptz default now());
create table remediations (id uuid primary key default gen_random_uuid(), finding_id text references findings(id), patch text, explanation text not null, status text not null default 'FIX_GENERATED', created_at timestamptz default now());
create table security_tests (id uuid primary key default gen_random_uuid(), finding_id text references findings(id), test_code text not null, status text not null, executed_at timestamptz);
alter table projects enable row level security; alter table scans enable row level security; alter table findings enable row level security; alter table remediations enable row level security; alter table security_tests enable row level security;
